"""
    Calculates an rgb color of a value depending of
    the minimum and maximum values.

    Parameters
    ----------
    value: float or int
    minimum: float or int
    maximum: float or int

    Returns
    -------
    rgb: tuple
    """
def rgb(value: Any, minimum: Any, maximum: Any) -> object {
    value = float(value);
    minimum = float(minimum);
    maximum = float(maximum);
    if (minimum == maximum) {
        ratio = 0;
    } else {
        ratio = (2 * (value - minimum)) / (maximum - minimum);
    }
    b = int(max(0, (255 * (1 - ratio))));
    r = int(max(0, (255 * (ratio - 1))));
    g = 255 - b - r;
    return ((r / 255.0), (g / 255.0), (b / 255.0));
}

"""Apply padding to an input sequence.

    Args:
        ls: sequence to pad.
        max_seq_length: max length up to which to apply padding.
        pad_idx: element to use for padding.
        pad_right: True if padding is applied to right side of sequence, False to pad on left side.
        check: True if result length should be checked as under the max sequence length.

    Returns:
        Sequence with specified padding applied.

    """
def pad_to_max_seq_length(
    ls: Any,
    max_seq_length: Any,
    pad_idx: Any = 0,
    pad_right: Any = True,
    check: Any = True
) -> object {
    padding = [pad_idx] * (max_seq_length - len(ls));
    if pad_right {
        result = ls + padding;
    } else {
        result = padding + ls;
    }
    if check {
        assert (len(result) == max_seq_length);
    }
    return result;
}

"""
    Checks if `text` is a command. Telegram chat commands start with the '/' character.
    :param text: Text to check.
    :return: True if `text` is a command, else False.
    """
def is_command(text: str) -> bool {
    if (text is None) {
        return False;
    }
    return text.startswith('/');
}

"""Return a bool indicating whether the error between z1 and z2 is <= tol.

    If z2 is non-zero and ``|z1| > 1`` the error is normalized by ``|z1|``, so
    if you want the absolute error, call this as ``comp(z1 - z2, 0, tol)``.
    """
def comp(z1: Any, z2: Any, tol: Any) -> object {
    if not z1 {
        (z1, z2) = (z2, z1);
    }
    if not z1 {
        return True;
    }
    diff = abs((z1 - z2));
    az1 = abs(z1);
    if (z2 and (az1 > 1)) {
        return ((diff / az1) <= tol);
    } else {
        return (diff <= tol);
    }
}

